29	/// Task polls shorter than this are folded into a [`PollSummary`] instead of
30	/// being recorded individually. This keeps the stream bounded by the number
31	/// of *slow* polls while preserving their exact count and total duration.
32	pub const TASK_POLL_FLOOR: Duration = Duration::from_micros(100);
33	
34	/// A dirty frame that has not been presented by this deadline stops blocking
35	/// foreground-idle boundaries, so a window that never presents (hidden or
36	/// occluded windows receive no frame callbacks) cannot suppress boundaries
37	/// indefinitely. Expiry only unblocks: the open interval still seals at a
38	/// real presentation or idle boundary, keeping a starving hang and the frame
39	/// it starved in one interval.
40	pub const FRAME_DEADLINE: Duration = Duration::from_secs(1);
41	
42	// Backstop against pathological event storms within a single interval. At the
43	// 100us floor, a fully hung second can produce at most ~10k recordable polls,
44	// so this bound is only reachable when something is already deeply wrong.
45	const MAX_INTERVAL_EVENTS: usize = 16 * 1024;
46	
47	// Allow 4MiB for the fixed ring allocation, including each slot's atomic
48	// metadata. The poll floor and frame cadence bound the event rate to roughly
49	// 10k per second in the worst case, so this holds several seconds of
50	// worst-case traffic between consumer drains.
51	const MAX_JOURNAL_ENTRIES: usize = (4 * 1024 * 1024) / core::mem::size_of::<JournalSlot>();
52	
53	// Absorbs brief collisions with a collector reading the exact slot being
54	// wrapped. The foreground never waits for a reader; queued entries are retried
55	// in order on the next publication.
56	const MAX_PENDING_JOURNAL_ENTRIES: usize = 64;
57	
58	/// One entry in the foreground stream.
59	///
60	/// Events are recorded in completion order (ordered by their end time). An
61	/// event that was in progress across a frame boundary (e.g. the task poll
62	/// enclosing a draw) is recorded when it *ends*, with timestamps that may
63	/// precede events recorded before it.
64	#[derive(Debug, Copy, Clone)]
65	pub enum ForegroundEvent {
66	    /// A foreground task poll at least [`TASK_POLL_FLOOR`] long.
67	    TaskPoll(TaskTiming),
68	    /// A completed action handler.
69	    Action(ActionTiming),
70	    /// A dispatched platform input event.
71	    Input(InputTiming),
72	    /// A completed window draw.
73	    Draw(FrameTiming),
74	    /// Work spent submitting a frame to the platform.
75	    Present(PresentTiming),
76	    /// Aggregate of task polls below [`TASK_POLL_FLOOR`], flushed before the
77	    /// next individually retained event or interval boundary.
78	    SmallPolls(SmallPollFlush),
79	}
80	
81	impl ForegroundEvent {
82	    /// When the work described by this event began. For draws this is the
83	    /// start of the draw itself, not the frame's first invalidation.
84	    pub fn start_time(&self) -> Instant {
85	        match self {
86	            Self::TaskPoll(timing) => timing.start,
87	            Self::Action(timing) => timing.start,
88	            Self::Input(timing) => timing.start,
89	            Self::Draw(timing) => timing.draw_start,
90	            Self::Present(timing) => timing.present_start,
91	            Self::SmallPolls(flush) => flush.since,
92	        }
93	    }
94	
95	    /// When the work described by this event ended.
96	    pub fn end_time(&self) -> Instant {
97	        match self {
98	            Self::TaskPoll(timing) => timing.end.0,
99	            Self::Action(timing) => timing.end,
100	            Self::Input(timing) => timing.end,
101	            Self::Draw(timing) => timing.draw_end,
102	            Self::Present(timing) => timing.present_end,
103	            Self::SmallPolls(flush) => flush.until,
104	        }
105	    }
106	
107	    /// How long the work described by this event took. For
108	    /// [`Self::SmallPolls`] this is the span the summary covers, not time
109	    /// spent polling; use the summary's `total` for occupancy.
110	    pub fn duration(&self) -> Duration {
111	        self.end_time().duration_since(self.start_time())
112	    }
113	}
