129	/// Exact count and total duration of task polls below [`TASK_POLL_FLOOR`].
130	#[derive(Debug, Copy, Clone, Default, PartialEq, Eq)]
131	pub struct PollSummary {
132	    /// Number of polls below the floor.
133	    pub count: u64,
134	    /// Total duration of polls below the floor.
135	    pub total: Duration,
136	}
137	
138	impl PollSummary {
139	    fn add(&mut self, other: Self) {
140	        self.count += other.count;
141	        self.total += other.total;
142	    }
143	}
