165	impl PresentedFrame {
166	    /// Time from the frame's first invalidation through platform submission.
167	    pub fn dirty_to_present_duration(&self) -> Option<Duration> {
168	        self.frame
169	            .dirty_at
170	            .map(|dirty_at| self.presentation.present_end.duration_since(dirty_at))
