174	/// The semantic event that completed a foreground activity interval.
175	#[derive(Debug, Copy, Clone)]
176	pub enum IntervalBoundary {
177	    /// A newly drawn frame was submitted to the platform.
178	    Presented(PresentedFrame),
179	    /// The foreground returned to an idle platform loop with no unexpired
180	    /// frame pending.
181	    Idle {
182	        /// When the foreground went idle.
183	        ended_at: Instant,
184	    },
185	}
186	
187	impl IntervalBoundary {
188	    /// When the interval ended.
189	    pub fn end_time(&self) -> Instant {
190	        match self {
191	            Self::Presented(presented) => presented.presentation.present_end,
192	            Self::Idle { ended_at } => *ended_at,
193	        }
194	    }
195	
196	    /// The first invalidation of the frame satisfied by this boundary, if any.
197	    pub fn dirty_at(&self) -> Option<Instant> {
198	        match self {
199	            Self::Presented(presented) => presented.frame.dirty_at,
200	            Self::Idle { .. } => None,
201	        }
202	    }
203	}
