225	/// One item retained in the foreground journal.
226	#[derive(Debug, Copy, Clone)]
227	pub enum ForegroundJournalEntry {
228	    /// A completed piece of foreground work.
229	    Event(ForegroundEvent),
230	    /// A semantic interval boundary.
231	    Boundary(IntervalBoundary),
232	    /// A change to pending-frame state. This is metadata, not foreground work.
233	    FrameState(FrameStateChange),
