242	/// An immutable view of one sealed foreground interval, produced by
243	/// [`IntervalSealer`].
244	#[derive(Debug, Clone)]
245	pub struct FrameSnapshot {
246	    /// When the interval started (the previous seal, or the end of the idle
247	    /// stretch preceding the interval's first event).
248	    pub interval_start: Instant,
249	    /// The semantic event that completed the interval, including its metadata.
250	    pub boundary: IntervalBoundary,
251	    /// Foreground work recorded during the interval, in completion order.
252	    /// [`ForegroundEvent::SmallPolls`] entries are collected into
253	    /// `small_polls` instead of appearing here.
254	    pub events: Vec<ForegroundEvent>,
255	    /// Span-tagged aggregates of task polls below [`TASK_POLL_FLOOR`]. Spans
256	    /// are retained so occupancy can apportion folded poll time to reporting
257	    /// windows narrower than the interval.
258	    pub small_polls: Vec<SmallPollFlush>,
259	    /// Events lost to the interval's event cap, plus ring losses reported
260	    /// via [`IntervalSealer::note_lost`].
261	    pub dropped_events: u64,
262	    /// Whether the journal had an unobserved gap during this interval.
263	    pub journal_discontinuous: bool,
264	}
265	
266	impl FrameSnapshot {
267	    /// When the interval ended.
268	    pub fn interval_end(&self) -> Instant {
269	        self.boundary.end_time()
270	    }
271	
272	    /// The combined count and total of all folded sub-floor polls in the
273	    /// interval.
274	    pub fn small_poll_summary(&self) -> PollSummary {
275	        let mut summary = PollSummary::default();
276	        for flush in &self.small_polls {
277	            summary.add(flush.summary);
278	        }
279	        summary
280	    }
281	
282	    /// Total foreground time occupied within the interval: the union of the
283	    /// recorded events' spans (clamped to the interval, so nested work like an
284	    /// action inside an input dispatch is not double counted) plus the folded
285	    /// small polls. Folded polls cannot be unioned with nested individually
286	    /// timed work, so this remains a close approximation.
287	    pub fn occupancy(&self) -> Duration {
288	        self.occupancy_within(self.interval_start, self.interval_end())
289	    }
290	
291	    /// Like [`Self::occupancy`], but measured against an arbitrary window
292	    /// (e.g. a reporting window anchored at a frame's first invalidation).
293	    /// Event spans are clamped to the window. Folded polls carry no
294	    /// individual timestamps, so each flush's total is apportioned by how
295	    /// much of its span overlaps the window — assuming the folded time is
296	    /// spread uniformly across the span.
297	    pub fn occupancy_within(&self, window_start: Instant, window_end: Instant) -> Duration {
298	        let mut spans: Vec<(Instant, Instant)> = self
299	            .events
300	            .iter()
301	            .map(|event| {
302	                let start = event.start_time().max(window_start);
303	                let end = event.end_time().min(window_end).max(start);
304	                (start, end)
305	            })
306	            .collect();
307	        spans.sort_by_key(|(start, _)| *start);
308	
309	        let mut occupied = Duration::ZERO;
310	        let mut merged_until: Option<Instant> = None;
311	        for (start, end) in spans {
312	            let start = match merged_until {
313	                Some(merged_until) => start.max(merged_until),
314	                None => start,
315	            };
316	            occupied += end.duration_since(start);
317	            merged_until = Some(match merged_until {
318	                Some(merged_until) => merged_until.max(end),
319	                None => end,
320	            });
321	        }
322	
323	        let apportioned_small_polls: Duration = self
324	            .small_polls
325	            .iter()
326	            .map(|flush| {
327	                let span = flush.until.duration_since(flush.since);
328	                if span.is_zero() {
329	                    // A point-like flush lies either inside or outside the
330	                    // window.
331	                    if flush.since >= window_start && flush.since <= window_end {
332	                        flush.summary.total
333	                    } else {
334	                        Duration::ZERO
335	                    }
336	                } else {
337	                    let overlap_start = flush.since.max(window_start);
338	                    let overlap_end = flush.until.min(window_end).max(overlap_start);
339	                    let overlap = overlap_end.duration_since(overlap_start);
340	                    flush.summary.total.mul_f64(overlap.div_duration_f64(span))
341	                }
342	            })
343	            .sum();
344	        occupied + apportioned_small_polls
345	    }
346	
347	    /// The fraction of the interval the foreground spent working, in `0.0..=1.0`.
348	    pub fn busy_fraction(&self) -> f64 {
349	        let interval = self.interval_end().duration_since(self.interval_start);
350	        if interval.is_zero() {
351	            return 1.0;
352	        }
353	        (self.occupancy().div_duration_f64(interval)).min(1.0)
354	    }
355	}
