524	thread_local! {
525	    static FOREGROUND_RUNNABLES: ForegroundRunnableCounter = ForegroundRunnableCounter::new();
526	    static FOREGROUND_JOURNAL: RefCell<Option<ForegroundJournalWriter>> = const { RefCell::new(None) };
527	}
528	
529	pub(crate) fn foreground_runnable_counter() -> ForegroundRunnableCounter {
530	    FOREGROUND_RUNNABLES.with(Clone::clone)
531	}
532	
533	/// Starts journaling on the calling thread. Called once by `App` construction
534	/// on the main thread; every other thread's recording calls are no-ops.
535	/// Idempotent so that multiple `App`s on one thread (tests) share one journal.
536	pub(crate) fn install_foreground_journal() -> ForegroundJournal {
537	    let foreground_runnables = foreground_runnable_counter();
538	    FOREGROUND_JOURNAL.with(|journal| {
539	        let mut journal = journal.borrow_mut();
540	        if let Some(journal) = journal.as_ref() {
541	            return ForegroundJournal {
542	                ring: Arc::clone(&journal.publisher.ring),
543	            };
544	        }
545	
546	        let (handle, publisher) =
547	            ForegroundJournal::new(MAX_JOURNAL_ENTRIES, MAX_PENDING_JOURNAL_ENTRIES);
548	        *journal = Some(ForegroundJournalWriter::new(
549	            foreground_runnables,
550	            publisher,
551	        ));
552	        handle
553	    })
554	}
