601	// TODO(gpui-profiler): the turn brackets in the dispatchers and
602	// WindowProfiler are bare begin/end call pairs rather than uses of this
603	// guard. A caught unwind between a pair leaves `turn_depth` (and potentially
604	// the runnable counter) permanently unbalanced, which silently disables
605	// idle boundaries for the rest of the process. Zed aborts on panics so
606	// this is latent today, but gpui-as-a-library callers may catch unwinds;
607	// route all bracketing through this guard.
608	pub(crate) struct ForegroundTurnGuard;
609	
610	impl Drop for ForegroundTurnGuard {
611	    fn drop(&mut self) {
612	        end_foreground_turn();
613	    }
614	}
615	
616	pub(crate) fn foreground_turn() -> ForegroundTurnGuard {
617	    begin_foreground_turn();
618	    ForegroundTurnGuard
619	}
620	
621	pub(crate) fn begin_foreground_turn() {
622	    with_journal(ForegroundJournalWriter::begin_turn);
623	}
624	
