666	const SLOT_WRITER: usize = 1 << (usize::BITS - 1);
667	const SLOT_READER_MASK: usize = !SLOT_WRITER;
668	const EMPTY_SEQUENCE: u64 = u64::MAX;
669	
670	struct JournalSlot {
671	    users: AtomicUsize,
672	    sequence: AtomicU64,
673	    entry: UnsafeCell<MaybeUninit<ForegroundJournalEntry>>,
674	}
675	
676	// `users` ensures the entry is only read while no writer owns the slot and is
677	// only written while no readers own it.
678	unsafe impl Sync for JournalSlot {}
679	
680	impl JournalSlot {
681	    fn new() -> Self {
682	        Self {
683	            users: AtomicUsize::new(0),
684	            sequence: AtomicU64::new(EMPTY_SEQUENCE),
685	            entry: UnsafeCell::new(MaybeUninit::uninit()),
686	        }
687	    }
688	
689	    fn try_publish(&self, sequence: u64, entry: ForegroundJournalEntry) -> bool {
690	        if self
691	            .users
692	            .compare_exchange(0, SLOT_WRITER, Ordering::Acquire, Ordering::Relaxed)
693	            .is_err()
694	        {
695	            return false;
696	        }
697	
698	        // SAFETY: setting SLOT_WRITER from zero gives this writer exclusive
699	        // access to the slot until the Release store below.
700	        unsafe {
701	            (*self.entry.get()).write(entry);
702	        }
703	        self.sequence.store(sequence, Ordering::Relaxed);
704	        self.users.store(0, Ordering::Release);
705	        true
706	    }
707	
708	    fn try_read(&self, expected_sequence: u64) -> Option<ForegroundJournalEntry> {
709	        let _guard = JournalSlotReadGuard::try_new(self)?;
710	        if self.sequence.load(Ordering::Relaxed) != expected_sequence {
711	            return None;
712	        }
713	
714	        // SAFETY: a matching sequence means the slot was initialized for this
715	        // logical entry, and `guard` prevents the writer from overwriting it
716	        // until after the Copy.
717	        Some(unsafe { *(*self.entry.get()).assume_init_ref() })
718	    }
719	
720	    fn try_add_reader(&self) -> bool {
721	        let mut users = self.users.load(Ordering::Relaxed);
722	        loop {
723	            if users & SLOT_WRITER != 0 || users == SLOT_READER_MASK {
724	                return false;
725	            }
726	            match self.users.compare_exchange_weak(
727	                users,
728	                users + 1,
729	                Ordering::Acquire,
730	                Ordering::Relaxed,
731	            ) {
732	                Ok(_) => return true,
733	                Err(updated_users) => users = updated_users,
734	            }
735	        }
736	    }
737	
738	    fn remove_reader(&self) {
739	        let previous = self.users.fetch_sub(1, Ordering::Release);
740	        debug_assert!(
741	            previous > 0 && previous & SLOT_WRITER == 0,
742	            "invalid slot reader state: {previous:#x}"
743	        );
744	    }
745	}
746	
747	struct JournalSlotReadGuard<'a> {
748	    slot: &'a JournalSlot,
749	}
750	
751	impl<'a> JournalSlotReadGuard<'a> {
752	    fn try_new(slot: &'a JournalSlot) -> Option<Self> {
753	        if slot.try_add_reader() {
754	            Some(Self { slot })
755	        } else {
756	            None
757	        }
758	    }
759	}
760	
761	impl Drop for JournalSlotReadGuard<'_> {
762	    fn drop(&mut self) {
763	        self.slot.remove_reader();
764	    }
765	}
