767	struct JournalRing {
768	    slots: Box<[JournalSlot]>,
769	    finalized: AtomicU64,
770	    offered: AtomicU64,
771	}
772	
773	impl JournalRing {
774	    fn new(capacity: usize) -> Self {
775	        let capacity = capacity.max(1);
776	        Self {
777	            slots: (0..capacity).map(|_| JournalSlot::new()).collect(),
778	            finalized: AtomicU64::new(0),
779	            offered: AtomicU64::new(0),
780	        }
781	    }
782	
783	    fn capacity(&self) -> usize {
784	        self.slots.len()
785	    }
786	
787	    fn try_publish(&self, sequence: u64, entry: ForegroundJournalEntry) -> bool {
788	        let index = (sequence % self.slots.len() as u64) as usize;
789	        self.slots[index].try_publish(sequence, entry)
790	    }
791	
792	    fn read(&self, sequence: u64) -> Option<ForegroundJournalEntry> {
793	        let index = (sequence % self.slots.len() as u64) as usize;
794	        self.slots[index].try_read(sequence)
795	    }
796	}
