798	struct PendingJournalEntry {
799	    sequence: u64,
800	    entry: ForegroundJournalEntry,
801	}
802	
803	struct JournalPublisher {
804	    ring: Arc<JournalRing>,
805	    next_sequence: u64,
806	    pending: VecDeque<PendingJournalEntry>,
807	    dropped_after_pending: u64,
808	    pending_capacity: usize,
809	}
810	
811	impl JournalPublisher {
812	    fn new(ring: Arc<JournalRing>, pending_capacity: usize) -> Self {
813	        Self {
814	            ring,
815	            next_sequence: 0,
816	            pending: VecDeque::with_capacity(pending_capacity),
817	            dropped_after_pending: 0,
818	            pending_capacity,
819	        }
820	    }
821	
822	    fn publish(&mut self, entries: impl IntoIterator<Item = ForegroundJournalEntry>) {
823	        for entry in entries {
824	            self.flush_pending();
825	            self.publish_one(entry);
826	        }
827	        self.flush_pending();
828	    }
829	
830	    fn publish_one(&mut self, entry: ForegroundJournalEntry) {
831	        let sequence = self.next_sequence;
832	        self.next_sequence += 1;
833	        self.ring
834	            .offered
835	            .store(self.next_sequence, Ordering::Release);
836	
837	        if !self.pending.is_empty() || self.dropped_after_pending > 0 {
838	            if self.dropped_after_pending == 0 && self.pending.len() < self.pending_capacity {
839	                self.pending
840	                    .push_back(PendingJournalEntry { sequence, entry });
841	            } else {
842	                self.dropped_after_pending += 1;
843	            }
844	            return;
845	        }
846	
847	        if self.ring.try_publish(sequence, entry) {
848	            self.ring.finalized.store(sequence + 1, Ordering::Release);
849	        } else if self.pending_capacity > 0 {
850	            self.pending
851	                .push_back(PendingJournalEntry { sequence, entry });
852	        } else {
853	            self.dropped_after_pending = 1;
854	        }
855	    }
856	
857	    fn flush_pending(&mut self) {
858	        while let Some(pending) = self.pending.front() {
859	            if !self.ring.try_publish(pending.sequence, pending.entry) {
860	                return;
861	            }
862	            let sequence = pending.sequence;
863	            self.pending.pop_front();
864	            self.ring.finalized.store(sequence + 1, Ordering::Release);
865	        }
866	
867	        if self.dropped_after_pending > 0 {
868	            self.ring
869	                .finalized
870	                .store(self.next_sequence, Ordering::Release);
871	            self.dropped_after_pending = 0;
872	        }
873	    }
874	}
