876	/// A cloneable handle to one foreground journal stream.
877	///
878	/// Each collector has an independent cursor. Collectors briefly pin one slot
879	/// at a time and never block recording; entries they could not observe are
880	/// reported as discontinuities. Apps on the same foreground thread share the
881	/// stream.
882	#[derive(Clone)]
883	pub struct ForegroundJournal {
884	    ring: Arc<JournalRing>,
885	}
886	
887	impl ForegroundJournal {
888	    fn new(capacity: usize, pending_capacity: usize) -> (Self, JournalPublisher) {
889	        let ring = Arc::new(JournalRing::new(capacity));
890	        (
891	            Self {
892	                ring: Arc::clone(&ring),
893	            },
894	            JournalPublisher::new(ring, pending_capacity),
895	        )
896	    }
897	
898	    /// Creates an independent collector that observes entries offered after
899	    /// this call.
900	    pub fn collector(&self) -> ForegroundJournalCollector {
901	        ForegroundJournalCollector {
902	            cursor: self.ring.offered.load(Ordering::Acquire),
903	            ring: Arc::clone(&self.ring),
904	        }
905	    }
