908	/// Entries returned by one [`ForegroundJournalCollector::collect_unseen`] call.
909	#[derive(Debug, Default)]
910	pub struct DrainedEntries {
911	    /// Journal entries recorded since the previous drain, in recording order,
912	    /// including synthetic [`ForegroundJournalEntry::Discontinuity`] markers at
913	    /// unavailable logical positions.
914	    pub entries: Vec<ForegroundJournalEntry>,
915	    /// Entries unavailable to this collector because they were overwritten or
916	    /// could not be published after the fixed pending queue filled. This is the
917	    /// aggregate of the discontinuity markers in `entries`.
918	    pub lost: u64,
919	}
920	
921	/// Reads the foreground stream, tracking a cursor so each call to
922	/// [`Self::collect_unseen`] returns only entries recorded since the previous
923	/// call. Independent collectors do not affect each other.
924	pub struct ForegroundJournalCollector {
925	    cursor: u64,
926	    ring: Arc<JournalRing>,
927	}
928	
929	impl ForegroundJournalCollector {
930	    /// Returns entries recorded since the previous call (or since the
931	    /// collector was created), reporting how many were unavailable before this
932	    /// drain observed them.
933	    pub fn collect_unseen(&mut self) -> DrainedEntries {
934	        let end = self.ring.finalized.load(Ordering::Acquire);
935	        if self.cursor >= end {
936	            return DrainedEntries::default();
937	        }
938	        let retained_start = end.saturating_sub(self.ring.capacity() as u64);
939	        let mut lost = retained_start.saturating_sub(self.cursor);
940	        self.cursor = self.cursor.max(retained_start);
941	        let mut entries = Vec::with_capacity((end - self.cursor) as usize + usize::from(lost > 0));
942	        if lost > 0 {
943	            entries.push(ForegroundJournalEntry::Discontinuity { lost });
944	        }
945	
946	        while self.cursor < end {
947	            if let Some(entry) = self.ring.read(self.cursor) {
948	                entries.push(entry);
949	            } else {
950	                lost += 1;
951	                match entries.last_mut() {
952	                    Some(ForegroundJournalEntry::Discontinuity { lost }) => *lost += 1,
953	                    _ => entries.push(ForegroundJournalEntry::Discontinuity { lost: 1 }),
954	                }
955	            }
956	            self.cursor += 1;
957	        }
958	
959	        DrainedEntries { entries, lost }
960	    }
961	}
