963	/// A pure state machine that groups foreground journal entries into
964	/// [`FrameSnapshot`]s.
965	///
966	/// Feed it drained entries in recording order. Work is carried across calls
967	/// until an explicit [`IntervalBoundary`] arrives. Idle time before an
968	/// interval's first event is excluded without relying on an elapsed-time
969	/// heuristic.
970	#[derive(Debug)]
971	pub struct IntervalSealer {
972	    interval_start: Instant,
973	    events: Vec<ForegroundEvent>,
974	    small_polls: Vec<SmallPollFlush>,
975	    dropped_events: u64,
976	    journal_discontinuous: bool,
977	}
978	
979	impl IntervalSealer {
980	    /// Creates a sealer whose first interval starts at `start` (typically
981	    /// the moment the consumer's collector was created).
982	    pub fn new(start: Instant) -> Self {
983	        Self {
984	            interval_start: start,
985	            events: Vec::new(),
986	            small_polls: Vec::new(),
987	            dropped_events: 0,
988	            journal_discontinuous: false,
989	        }
990	    }
991	
992	    /// Accounts for a loss supplied outside a collector drain. Collector losses
993	    /// are already represented by ordered discontinuity entries.
994	    pub fn note_lost(&mut self, lost: u64) {
995	        self.dropped_events += lost;
996	        self.journal_discontinuous |= lost > 0;
997	    }
998	
999	    /// Processes a batch of drained entries, returning the snapshots completed
1000	    /// by explicit boundaries. Work without a following boundary is carried
1001	    /// over to subsequent calls.
1002	    pub fn push_entries(
1003	        &mut self,
1004	        entries: impl IntoIterator<Item = ForegroundJournalEntry>,
1005	    ) -> Vec<FrameSnapshot> {
1006	        let mut snapshots = Vec::new();
1007	        for entry in entries {
1008	            match entry {
1009	                ForegroundJournalEntry::Event(event) => {
1010	                    if self.is_empty() {
1011	                        self.interval_start = self.interval_start.max(event.start_time());
1012	                    }
1013	                    match event {
1014	                        ForegroundEvent::SmallPolls(flush) => self.push_small_polls(flush),
1015	                        event => self.push_event(event),
1016	                    }
1017	                }
1018	                ForegroundJournalEntry::Boundary(boundary) => {
1019	                    if let IntervalBoundary::Presented(presented) = boundary {
1020	                        if self.is_empty() {
1021	                            self.interval_start = self
1022	                                .interval_start
1023	                                .max(presented.presentation.present_start);
1024	                        }
1025	                        self.push_event(ForegroundEvent::Present(presented.presentation));
1026	                    }
1027	                    if self.is_empty() {
1028	                        self.interval_start = self.interval_start.max(boundary.end_time());
1029	                    } else {
1030	                        snapshots.push(self.seal(boundary));
1031	                    }
1032	                }
1033	                // Pending-frame state gates boundaries on the writer side;
1034	                // the entries remain in the stream for consumers that want
1035	                // dirty timing, but the sealer has no use for them.
1036	                ForegroundJournalEntry::FrameState(_) => {}
1037	                ForegroundJournalEntry::Discontinuity { lost } => self.note_lost(lost),
1038	            }
1039	        }
1040	        snapshots
1041	    }
1042	
1043	    fn is_empty(&self) -> bool {
1044	        self.events.is_empty()
1045	            && self.small_polls.is_empty()
1046	            && self.dropped_events == 0
1047	            && !self.journal_discontinuous
1048	    }
1049	
1050	    fn push_event(&mut self, event: ForegroundEvent) {
1051	        if self.events.len() >= MAX_INTERVAL_EVENTS {
1052	            self.dropped_events += 1;
1053	        } else {
1054	            self.events.push(event);
1055	        }
1056	    }
1057	
1058	    fn push_small_polls(&mut self, flush: SmallPollFlush) {
1059	        if self.small_polls.len() >= MAX_INTERVAL_EVENTS
1060	            && let Some(last) = self.small_polls.last_mut()
1061	        {
1062	            // Degrade gracefully at the cap: widen the last flush's span
1063	            // instead of dropping poll time, at the cost of coarser
1064	            // apportioning.
1065	            last.summary.add(flush.summary);
1066	            last.since = last.since.min(flush.since);
1067	            last.until = last.until.max(flush.until);
1068	        } else {
1069	            self.small_polls.push(flush);
1070	        }
1071	    }
1072	
1073	    fn seal(&mut self, boundary: IntervalBoundary) -> FrameSnapshot {
1074	        let ended = boundary.end_time();
1075	        let snapshot = FrameSnapshot {
1076	            interval_start: self.interval_start,
1077	            boundary,
1078	            events: std::mem::take(&mut self.events),
1079	            small_polls: std::mem::take(&mut self.small_polls),
1080	            dropped_events: std::mem::take(&mut self.dropped_events),
1081	            journal_discontinuous: std::mem::take(&mut self.journal_discontinuous),
1082	        };
1083	        self.interval_start = ended;
1084	        snapshot
1085	    }
1086	}
