1673	        let mut collector = journal.collector();
1674	        let done = Arc::new(std::sync::atomic::AtomicBool::new(false));
1675	        let collector_done = Arc::clone(&done);
1676	        let collector_task = std::thread::spawn(move || {
1677	            let mut observed = Vec::new();
1678	            loop {
1679	                let drained = collector.collect_unseen();
1680	                observed.extend(normalize_ring_drain(origin, drained.entries));
1681	                if collector_done.load(Ordering::Acquire) {
1682	                    let drained = collector.collect_unseen();
1683	                    observed.extend(normalize_ring_drain(origin, drained.entries));
1684	                    return (collector, observed);
1685	                }
1686	                std::thread::yield_now();
1687	            }
1688	        });
1689	
1690	        for sequence in 0..ENTRY_COUNT {
1691	            publisher.publish([ring_entry(origin, sequence)]);
1692	        }
1693	        done.store(true, Ordering::Release);
1694	
1695	        let (mut collector, mut observed) = collector_task
1696	            .join()
1697	            .expect("collector thread should not panic");
1698	        publisher.flush_pending();
1699	        observed.extend(normalize_ring_drain(
1700	            origin,
1701	            collector.collect_unseen().entries,
1702	        ));
1703	
1704	        let mut expected_sequence = 0;
1705	        for entry in observed {
1706	            match entry {
1707	                ModelDrainEntry::Entry(sequence) => {
1708	                    assert_eq!(sequence, expected_sequence);
1709	                    expected_sequence += 1;
1710	                }
1711	                ModelDrainEntry::Discontinuity(lost) => expected_sequence += lost,
1712	            }
1713	        }
1714	        assert_eq!(expected_sequence, ENTRY_COUNT);
1715	        assert_eq!(
1716	            publisher.ring.finalized.load(Ordering::Acquire),
1717	            ENTRY_COUNT
1718	        );
1719	    }
1720	
1721	    #[derive(Clone, Debug)]
1722	    enum RingOperation {
1723	        Publish,
1724	        Collect(u8),
1725	        NewCollector,
1726	        Pin(u8),
1727	        Unpin(u8),
1728	    }
1729	
1730	    #[derive(Clone, Debug, PartialEq, Eq)]
1731	    enum ModelDrainEntry {
1732	        Entry(u64),
1733	        Discontinuity(u64),
1734	    }
1735	
1736	    struct ModelRing {
1737	        capacity: usize,
1738	        pending_capacity: usize,
1739	        next_sequence: u64,
1740	        finalized: u64,
1741	        offered: u64,
1742	        slots: Vec<Option<(u64, u64)>>,
1743	        pinned: Vec<bool>,
1744	        pending: VecDeque<(u64, u64)>,
1745	        dropped_after_pending: u64,
1746	    }
1747	
1748	    impl ModelRing {
1749	        fn new(capacity: usize, pending_capacity: usize) -> Self {
1750	            Self {
1751	                capacity,
1752	                pending_capacity,
1753	                next_sequence: 0,
1754	                finalized: 0,
1755	                offered: 0,
1756	                slots: vec![None; capacity],
1757	                pinned: vec![false; capacity],
1758	                pending: VecDeque::new(),
1759	                dropped_after_pending: 0,
1760	            }
1761	        }
1762	
1763	        fn publish(&mut self) {
1764	            self.flush_pending();
1765	            let sequence = self.next_sequence;
1766	            self.next_sequence += 1;
1767	            self.offered = self.next_sequence;
1768	
1769	            if !self.pending.is_empty() || self.dropped_after_pending > 0 {
1770	                if self.dropped_after_pending == 0 && self.pending.len() < self.pending_capacity {
1771	                    self.pending.push_back((sequence, sequence));
1772	                } else {
1773	                    self.dropped_after_pending += 1;
1774	                }
1775	            } else {
1776	                let index = sequence as usize % self.capacity;
1777	                if self.pinned[index] {
1778	                    if self.pending_capacity > 0 {
1779	                        self.pending.push_back((sequence, sequence));
1780	                    } else {
1781	                        self.dropped_after_pending = 1;
1782	                    }
1783	                } else {
1784	                    self.slots[index] = Some((sequence, sequence));
1785	                    self.finalized = sequence + 1;
1786	                }
1787	            }
1788	            self.flush_pending();
1789	        }
1790	
1791	        fn flush_pending(&mut self) {
1792	            while let Some(&(sequence, value)) = self.pending.front() {
1793	                let index = sequence as usize % self.capacity;
1794	                if self.pinned[index] {
1795	                    return;
1796	                }
1797	                self.slots[index] = Some((sequence, value));
1798	                self.pending.pop_front();
1799	                self.finalized = sequence + 1;
1800	            }
1801	
1802	            if self.dropped_after_pending > 0 {
1803	                self.finalized = self.next_sequence;
1804	                self.dropped_after_pending = 0;
1805	            }
1806	        }
1807	
1808	        fn collect(&self, cursor: &mut u64) -> (Vec<ModelDrainEntry>, u64) {
1809	            let end = self.finalized;
1810	            if *cursor >= end {
1811	                return (Vec::new(), 0);
1812	            }
1813	
1814	            let retained_start = end.saturating_sub(self.capacity as u64);
1815	            let mut lost = retained_start.saturating_sub(*cursor);
1816	            *cursor = (*cursor).max(retained_start);
1817	            let mut entries = Vec::new();
1818	            if lost > 0 {
1819	                entries.push(ModelDrainEntry::Discontinuity(lost));
1820	            }
1821	            while *cursor < end {
1822	                let index = *cursor as usize % self.capacity;
1823	                match self.slots[index] {
1824	                    Some((sequence, value)) if sequence == *cursor => {
1825	                        entries.push(ModelDrainEntry::Entry(value));
1826	                    }
1827	                    _ => {
1828	                        lost += 1;
1829	                        match entries.last_mut() {
1830	                            Some(ModelDrainEntry::Discontinuity(lost)) => *lost += 1,
1831	                            _ => entries.push(ModelDrainEntry::Discontinuity(1)),
1832	                        }
1833	                    }
1834	                }
1835	                *cursor += 1;
1836	            }
1837	            (entries, lost)
1838	        }
1839	    }
