1911	                match kind % 7 {
1912	                    0 => input_entry(start, end),
1913	                    1 => ForegroundJournalEntry::Event(ForegroundEvent::Action(ActionTiming {
1914	                        name: "test.action",
1915	                        start,
1916	                        end,
1917	                    })),
1918	                    2 => ForegroundJournalEntry::Event(ForegroundEvent::TaskPoll(task_timing(
1919	                        start, end,
1920	                    ))),
1921	                    3 => {
1922	                        ForegroundJournalEntry::Event(ForegroundEvent::SmallPolls(SmallPollFlush {
1923	                            summary: PollSummary {
1924	                                count: u64::from(*span % 5) + 1,
