2013	    fn reference_seal(
2014	        origin: Instant,
2015	        entries: &[ForegroundJournalEntry],
2016	    ) -> (Vec<NormalizedSnapshot>, NormalizedSealerTail) {
2017	        let mut interval_start = 0;
2018	        let mut events = Vec::new();
2019	        let mut small_polls = Vec::new();
2020	        let mut snapshots = Vec::new();
2021	        let mut dropped_events = 0;
2022	        let mut journal_discontinuous = false;
2023	
2024	        for entry in entries {
2025	            match *entry {
2026	                ForegroundJournalEntry::Event(event) => {
2027	                    let event_start = event.start_time().duration_since(origin).as_micros() as u64;
2028	                    if events.is_empty()
2029	                        && small_polls.is_empty()
2030	                        && dropped_events == 0
2031	                        && !journal_discontinuous
2032	                    {
2033	                        interval_start = interval_start.max(event_start);
2034	                    }
2035	                    match event {
2036	                        ForegroundEvent::SmallPolls(flush) => {
2037	                            small_polls.push(normalize_small_polls(origin, flush));
2038	                        }
2039	                        event => events.push(normalize_event(origin, event)),
2040	                    }
2041	                }
2042	                ForegroundJournalEntry::Boundary(boundary) => {
2043	                    if let IntervalBoundary::Presented(presented) = boundary {
2044	                        let present = ForegroundEvent::Present(presented.presentation);
2045	                        if events.is_empty()
2046	                            && small_polls.is_empty()
2047	                            && dropped_events == 0
2048	                            && !journal_discontinuous
2049	                        {
2050	                            interval_start =
2051	                                interval_start
2052	                                    .max(present.start_time().duration_since(origin).as_micros()
2053	                                        as u64);
2054	                        }
2055	                        events.push(normalize_event(origin, present));
2056	                    }
2057	
2058	                    let interval_end =
2059	                        boundary.end_time().duration_since(origin).as_micros() as u64;
2060	                    if events.is_empty()
2061	                        && small_polls.is_empty()
2062	                        && dropped_events == 0
2063	                        && !journal_discontinuous
2064	                    {
2065	                        interval_start = interval_start.max(interval_end);
2066	                    } else {
2067	                        snapshots.push(NormalizedSnapshot {
2068	                            interval_start,
2069	                            boundary_kind: match boundary {
2070	                                IntervalBoundary::Idle { .. } => 0,
2071	                                IntervalBoundary::Presented(_) => 1,
2072	                            },
2073	                            interval_end,
2074	                            events: std::mem::take(&mut events),
2075	                            small_polls: std::mem::take(&mut small_polls),
2076	                            dropped_events: std::mem::take(&mut dropped_events),
2077	                            journal_discontinuous: std::mem::take(&mut journal_discontinuous),
2078	                        });
2079	                        interval_start = interval_end;
2080	                    }
2081	                }
2082	                ForegroundJournalEntry::FrameState(_) => {}
2083	                ForegroundJournalEntry::Discontinuity { lost } => {
2084	                    dropped_events += lost;
2085	                    journal_discontinuous = true;
2086	                }
2087	            }
2088	        }
2089	
2090	        (
2091	            snapshots,
2092	            NormalizedSealerTail {
2093	                interval_start,
2094	                events,
2095	                small_polls,
2096	                dropped_events,
2097	                journal_discontinuous,
2098	            },
2099	        )
2100	    }
