2102	    fn reference_occupancy_micros(
2103	        event_spans: &[(u8, u8)],
2104	        small_poll_spans: &[(u8, u8, u8)],
2105	        window_start: u8,
2106	        window_end: u8,
2107	    ) -> u64 {
2108	        let mut clamped_spans = event_spans
2109	            .iter()
2110	            .map(|&(first, second)| {
2111	                let start = first.min(second).max(window_start);
2112	                let end = first.max(second).min(window_end).max(start);
2113	                (start, end)
2114	            })
2115	            .collect::<Vec<_>>();
2116	        clamped_spans.sort_unstable();
2117	
2118	        let mut occupied = 0u64;
2119	        let mut merged_until = None;
2120	        for (start, end) in clamped_spans {
2121	            let start = merged_until.map_or(start, |until| start.max(until));
2122	            occupied += u64::from(end.saturating_sub(start));
2123	            merged_until = Some(merged_until.map_or(end, |until| until.max(end)));
2124	        }
2125	
2126	        occupied
2127	            + small_poll_spans
2128	                .iter()
2129	                .map(|&(first, second, factor)| {
2130	                    let since = first.min(second);
2131	                    let until = first.max(second);
2132	                    if since == until {
2133	                        if since >= window_start && since <= window_end {
2134	                            u64::from(factor)
2135	                        } else {
2136	                            0
2137	                        }
2138	                    } else {
2139	                        let overlap_start = since.max(window_start);
2140	                        let overlap_end = until.min(window_end).max(overlap_start);
2141	                        u64::from(overlap_end - overlap_start) * u64::from(factor)
2142	                    }
2143	                })
2144	                .sum::<u64>()
2145	    }
