2344	            pending_capacity in 0usize..=4,
2345	            operations in prop::collection::vec(
2346	                prop_oneof![
2347	                    5 => Just(RingOperation::Publish),
2348	                    3 => any::<u8>().prop_map(RingOperation::Collect),
2349	                    1 => Just(RingOperation::NewCollector),
2350	                    2 => any::<u8>().prop_map(RingOperation::Pin),
2351	                    2 => any::<u8>().prop_map(RingOperation::Unpin),
2352	                ],
2353	                1..=128,
2354	            ),
2355	        ) {
2356	            let origin = Instant::now();
2357	            let (journal, mut publisher) = ForegroundJournal::new(capacity, pending_capacity);
2358	            let mut collectors = vec![journal.collector()];
2359	            let mut model_collectors = vec![0];
2360	            let mut model = ModelRing::new(capacity, pending_capacity);
2361	            let mut pins: Vec<Option<JournalSlotReadGuard<'_>>> =
2362	                (0..capacity).map(|_| None).collect();
2363	
2364	            for operation in operations {
2365	                match operation {
2366	                    RingOperation::Publish => {
2367	                        let sequence = model.next_sequence;
2368	                        publisher.publish([ring_entry(origin, sequence)]);
2369	                        model.publish();
2370	                    }
2371	                    RingOperation::Collect(collector) => {
2372	                        let index = usize::from(collector) % collectors.len();
2373	                        let drained = collectors[index].collect_unseen();
2374	                        let (expected_entries, expected_lost) =
2375	                            model.collect(&mut model_collectors[index]);
2376	                        let observed_entries = normalize_ring_drain(origin, drained.entries);
2377	                        prop_assert_eq!(observed_entries, expected_entries);
2378	                        prop_assert_eq!(drained.lost, expected_lost);
2379	                    }
2380	                    RingOperation::NewCollector if collectors.len() < 4 => {
2381	                        collectors.push(journal.collector());
2382	                        model_collectors.push(model.offered);
2383	                    }
2384	                    RingOperation::NewCollector => {}
2385	                    RingOperation::Pin(slot) => {
2386	                        let index = usize::from(slot) % capacity;
2387	                        if pins[index].is_none() {
