2403	                    model.offered
2404	                );
2405	                prop_assert_eq!(
2406	                    publisher.ring.finalized.load(Ordering::Acquire),
2407	                    model.finalized
2408	                );
2409	                prop_assert_eq!(
2410	                    publisher
2411	                        .pending
2412	                        .iter()
2413	                        .map(|entry| entry.sequence)
2414	                        .collect::<Vec<_>>(),
2415	                    model
2416	                        .pending
2417	                        .iter()
2418	                        .map(|(sequence, _)| *sequence)
