516	/// Upgrades all live per-thread timing handles, holding the global registry
517	/// lock only for the duration of the upgrades.
518	///
519	/// The upgraded `Arc`s must never be dropped while `GLOBAL_THREAD_TIMINGS` is
520	/// locked: dropping the last strong reference runs [`ThreadTimings::drop`],
521	/// which locks `GLOBAL_THREAD_TIMINGS` again and would deadlock the
522	/// non-reentrant spinlock. A thread exiting concurrently can hand off its last
523	/// reference to us at any time, so callers of this function process (lock,
524	/// read, drop) the returned handles only after the global lock is released.
525	fn upgraded_thread_timings() -> Vec<(ThreadId, Arc<GuardedTaskTimings>)> {
526	    let global_thread_timings = GLOBAL_THREAD_TIMINGS.lock();
527	    global_thread_timings
528	        .iter()
529	        .filter_map(|t| Some((t.thread_id, t.timings.upgrade()?)))
530	        .collect()
