696	const TRACE_SETTING_ENABLED: u64 = 1 << 63;
697	const TRACE_SCOPE_COUNT_MASK: u64 = TRACE_SETTING_ENABLED - 1;
698	static TRACE_STATE: AtomicU64 = AtomicU64::new(0);
699	
700	/// Enables or disables profiler trace collection at runtime.
701	///
702	/// When transitioning from enabled to disabled, `add_task_timing` becomes
703	/// cheaper since only cheap statistics are gathered. The existing per-thread
704	/// task buffers and the frame-event buffer are cleared so stale data isn't
705	/// reported after a later re-enable. Active trace scopes keep collection enabled
706	/// until the last scope ends. Calls with the current setting are a no-op.
707	pub fn set_trace_enabled(enabled: bool) -> bool {
708	    let mut state = TRACE_STATE.load(Ordering::Acquire);
709	    loop {
710	        let was_enabled = state & TRACE_SETTING_ENABLED != 0;
711	        if was_enabled == enabled {
712	            return false;
713	        }
714	
715	        let next_state = if enabled {
716	            state | TRACE_SETTING_ENABLED
717	        } else {
718	            state & TRACE_SCOPE_COUNT_MASK
719	        };
720	        match TRACE_STATE.compare_exchange_weak(
721	            state,
722	            next_state,
723	            Ordering::AcqRel,
724	            Ordering::Acquire,
725	        ) {
726	            Ok(_) => {
727	                if next_state == 0 {
728	                    clear_trace_buffers();
729	                }
730	                return true;
731	            }
732	            Err(updated_state) => state = updated_state,
733	        }
734	    }
735	}
