1182	/// Drains frame events recorded after this collector was created, tracking a
1183	/// cursor so each call to [`Self::collect_unseen`] returns only new entries.
1184	#[cfg(feature = "profiler")]
1185	pub struct FrameTimingCollector {
1186	    cursor: u64,
1187	}
